/**
 * A small CSS reader for the design-system guards and the contrast test (ADR-0010 sections 1, 2
 * and 4). It is not a CSS engine: it understands blocks, declarations, `var()` chains and the few
 * colour forms `tokens.css` is allowed to use (6-digit hex, `color-mix(in srgb, <hex> N%,
 * transparent)`, `linear-gradient(<angle>, <colour> <position>, ...)` and the texture's
 * `radial-gradient`). Pure functions, no Angular, no file access.
 */
import type { RGB, RGBA } from './contrast';
import { hexToRgb } from './contrast';

export interface Decl {
  /** Identifier of the innermost block (see `Block.id`), -1 at the top level. */
  blockId: number;
  /** The preludes of the enclosing blocks, outermost first (`['@media (...)', '.card']`). */
  stack: string[];
  prop: string;
  value: string;
}

export interface Block {
  /** Position of the block in the file, so two blocks with the same prelude stay apart. */
  id: number;
  stack: string[];
  prelude: string;
}

export function stripComments(css: string): string {
  return css.replace(/\/\*[\s\S]*?\*\//g, '');
}

/**
 * Boots the real application routes (`appConfig` + `routes`) in the zoneless TestBed with the
 * content API replaced by a `ContentServer`. Component tests of the wizard go through the router,
 * as a person does, so they do not depend on component class names, selectors or input bindings.
 *
 * Usage:
 *   beforeEach(() => configureAppTest());
 *   it('...', async () => {
 *     const app = await createAppTest();
 *     await app.open('/co/datos');
 *     ... act on app.root, then `await app.settle()` ...
 *   });
 *
 * A test that scripts a request to never be answered (`'hang'`) must call `vi.useFakeTimers()`
 * BEFORE `createAppTest()` and restore real timers afterwards; it then advances time itself.
 */
import { Location } from '@angular/common';
import { provideLocationMocks } from '@angular/common/testing';
import { provideHttpClientTesting, HttpTestingController } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { Router } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
