    const metas = tagsOf(indexHtml(), 'meta').filter((m) => m['name'] === 'theme-color');
    expect(metas).toHaveLength(1);
    const [solid] = coloursOf(tokens(), '--component-header-bg-solid');
    expect(metas[0]['content'].toLowerCase()).toBe(toHex(solid.rgb));
