    expect(statSync(join(PUBLIC, 'favicon.svg')).size).toBeLessThanOrEqual(4096);
  });

  it('US-04-AC-31 favicon.svg has no <text>, no <script>, no "http" or "//" reference and no href or xlink:href to another file', () => {
