    const svg = readFileSync(join(PUBLIC, 'favicon.svg'), 'utf8');
    const box = /viewBox\s*=\s*["']\s*([-\d.]+)[\s,]+([-\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)\s*["']/.exec(svg);
